namespace ghidra.app.plugin.core.symboltree.nodes;





using docking.widgets.tree;
using generic.theme;
using ghidra.app.plugin.core.symboltree;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util.task;

class ExportsCategoryNode : SymbolCategoryNode {
	private static readonly Icon OPEN_FOLDER =
		new GIcon("icon.plugin.symboltree.node.category.exports.open");
	private static readonly Icon CLOSED_FOLDER =
		new GIcon("icon.plugin.symboltree.node.category.exports.closed");

	public ExportsCategoryNode(Program program) : base(SymbolCategory.EXPORTS_CATEGORY, program)
    {
	}

	/* @Override */
	public List<GTreeNode> generateChildren(TaskMonitor monitor) {
		if (!isEnabled) {
			return Collections.emptyList();
		}

		List<GTreeNode> list = new();
		List<Symbol> functionSymbolList = getExportSymbols();
		foreach (Symbol symbol in functionSymbolList) {
			list.add(SymbolNode.createNode(symbol, program));
		}

		Collections.sort(list, getChildrenComparator());

		return list;
	}

	private List<Symbol> getExportSymbols() {
		List<Symbol> symbols = new();
		AddressIterator iterator = symbolTable.getExternalEntryPointIterator();
		while (_iterator.hasNext()) {
			Symbol symbol = symbolTable.getPrimarySymbol(_iterator.next());
			if (symbol != null) {
				symbols.add(symbol);
			}
		}
		return symbols;
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return expanded ? OPEN_FOLDER : CLOSED_FOLDER;
	}

	/* @Override */
	protected bool supportsSymbol(Symbol symbol) {
		if (!symbol.isPrimary()) {
			return false;
		}

		if (symbol.isExternalEntryPoint()) {
			return true;
		}

		Symbol parent = symbol.getParentSymbol();
		return parent != null && parent.isExternalEntryPoint();
	}
}
